import unittest
from unittest.mock import patch
import pytest
from candidate import greatest_common_divisor

class TestGreatestCommonDivisor(unittest.TestCase):
    @patch('candidate.greatest_common_divisor', side_effect=lambda x, y: x % y)
    def test_gcd_works_with_positive_integers(self, mock_gcd):
        mock_gcd.side_effect = greatest_common_divisor
        self.assertEqual(greatest_common_divisor(3, 5), 1)
        self.assertEqual(greatest_common_divisor(25, 15), 5)

    def test_gcd_with_zero(self):
        with self.assertRaises(ZeroDivisionError):
            greatest_common_divisor(0, 0)

    def test_gcd_with_negative_numbers(self):
        self.assertEqual(greatest_common_divisor(-3, 5), 1)
        self.assertEqual(greatest_common_divisor(-3, -5), 1)
        self.assertEqual(greatest_common_divisor(-3, 0), 3)
        self.assertEqual(greatest_common_divisor(0, -5), 5)

    def test_gcd_with_one(self):
        self.assertEqual(greatest_common_divisor(1, 5), 1)
        self.assertEqual(greatest_common_divisor(5, 1), 1)

    def test_gcd_with_negative(self):
        self.assertEqual(greatest_common_divisor(-3, -5), 1)

    def test_gcd_with_large_numbers(self):
        self.assertEqual(greatest_common_divisor(1000, 3000), 1000)

    def test_gcd_with_large_numbers_one_smaller(self):
        self.assertEqual(greatest_common_divisor(1001, 3000), 1)

    def test_gcd_with_large_numbers_one_larger(self):
        self.assertEqual(greatest_common_divisor(3001, 1000), 1)

    def test_gcd_with_large_numbers_same(self):
        self.assertEqual(greatest_common_divisor(123456789, 123456789), 123456789)

    def test_gcd_with_large_numbers_different(self):
        self.assertEqual(greatest_common_divisor(1234567890, 1234567880), 10)

    def test_gcd_with_large_numbers_one_negative(self):
        self.assertEqual(greatest_common_divisor(-123456789, 123456789), 123456789)

    def test_gcd_with_large_numbers_one_negative_other_positive(self):
        self.assertEqual(greatest_common_divisor(-123456789, 1234567890), 123456789)

    def test_gcd_with_large_numbers_negative_both(self):
        self.assertEqual(greatest_common_divisor(-1234567890, -1234567890), 1234567890)

    def test_gcd_with_large_numbers_one_negative_other_negative(self):
        self.assertEqual(greatest_common_divisor(-1234567890, -1234567891), 1)

